//! 🧪️ Real clock producer replies remain bound to their original Source.
use super::*;
use semio_framework_value_control_contract::{OriginalSourceTurn,OriginalSourceTurnIssuer,OriginalSourceTurnIssuerIdentity};
use std::sync::{Arc,atomic::{AtomicUsize,Ordering}};
struct Interrupted{issuer:OriginalSourceTurnIssuerIdentity,calls:Arc<AtomicUsize>,recoveries:Arc<AtomicUsize>}
impl OriginalClockProducer for Interrupted{
 type Context<'a,'b>=OriginalSystemClockContext<'a> where 'b:'a;
 fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{if c.issuer.identity()!=self.issuer{return Err(invalid())}c.issuer.validate(c.turn)?;Ok(())}
 fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity> where 'b:'a{Some(c.turn.identity())}
 fn read<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,reply:OriginalClockReply<'r>)->Result<OriginalClockReplyComplete<'r>,ValueError> where 'b:'a{self.calls.fetch_add(1,Ordering::Relaxed);let _reply=reply.complete(Ok(Some(99)));panic!("actual clock producer after recording")}
 fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,reply:OriginalClockReply<'r>)->Result<OriginalClockReplyComplete<'r>,ValueError> where 'b:'a{self.recoveries.fetch_add(1,Ordering::Relaxed);Ok(reply.pending())}
}
#[test]
fn recorded_clock_reply_survives_producer_and_wrapper_unwind(){
 let cases:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/⏱️recorded/cases.json")).unwrap();let issuer=OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();let foreign_issuer=OriginalSourceTurnIssuer::new();let foreign=foreign_issuer.issue().unwrap();let calls=Arc::new(AtomicUsize::new(0));let recoveries=Arc::new(AtomicUsize::new(0));let mut owner=OriginalClockAuthority::new(Interrupted{issuer:issuer.identity(),calls:calls.clone(),recoveries:recoveries.clone()});let mut context=OriginalSystemClockContext::new(&issuer,&turn).unwrap();let mut wrong=OriginalSystemClockContext::new(&foreign_issuer,&foreign).unwrap();let mut action=None;let mut reading=None;
 let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||owner.drive(&mut context,&mut action).unwrap()));assert!(interrupted.is_err());assert!(owner.has_pending_action());assert!(owner.drive(&mut wrong,&mut action).is_err());assert!(owner.drive(&mut context,&mut action).unwrap());let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{assert!(action.as_mut().unwrap().transfer_reading(&mut reading).unwrap());panic!("wrapper after resident clock reading")}));assert!(interrupted.is_err());let observation=*reading.as_ref().unwrap().as_ref().unwrap();assert_eq!(observation.reading(),Some(99));assert!(observation.monotonic());let deadline=owner.deadline_from(&context,observation,1).unwrap();assert!(!owner.should_yield(&context,deadline,observation,5).unwrap());assert_eq!(cases[2]["yield"],false);assert!(owner.finish(&wrong,&mut action).is_err());assert!(owner.has_pending_action());owner.finish(&context,&mut action).unwrap();assert_eq!(calls.load(Ordering::Relaxed),1);assert_eq!(recoveries.load(Ordering::Relaxed),0);assert!(owner.into_producer().is_ok())
}
#[cfg(any(not(target_arch="wasm32"),target_env="p2"))]
#[test]
fn system_clock_reads_its_actual_source_and_rejects_a_foreign_issuer(){
 let issuer=OriginalSourceTurnIssuer::new();let turn:OriginalSourceTurn=issuer.issue().unwrap();let alien=OriginalSourceTurnIssuer::new();let wrong=alien.issue().unwrap();let mut authority=OriginalClockAuthority::new(OriginalSystemClock::new(&issuer));assert!(authority.inspect(|clock|clock.origin.is_none()));let mut actual=OriginalSystemClockContext::new(&issuer,&turn).unwrap();let mut foreign=OriginalSystemClockContext::new(&alien,&wrong).unwrap();let mut action=None;let mut reading=None;assert!(authority.drive(&mut foreign,&mut action).is_err());assert!(action.is_none());assert!(authority.inspect(|clock|clock.origin.is_none()));assert!(authority.drive(&mut actual,&mut action).unwrap());assert!(authority.inspect(|clock|clock.origin.is_some()));assert!(action.as_mut().unwrap().transfer_reading(&mut reading).unwrap());let observation=reading.take().unwrap().unwrap();assert!(observation.reading().is_some()&&observation.monotonic());let deadline=authority.deadline_from(&actual,observation,10_000).unwrap();authority.finish(&actual,&mut action).unwrap();let mut other=OriginalClockAuthority::new(OriginalSystemClock::new(&issuer));let mut denied=OriginalClockDecisionFrame::new();assert_eq!(denied.poll(&mut other,&mut actual,deadline,1).unwrap(),OriginalClockDecisionStatus::Refused);assert!(!other.has_pending_action());assert!(other.inspect(|clock|clock.origin.is_none()));let mut refusal=None;assert!(denied.transfer_refusal(&mut refusal).unwrap());drop(refusal);denied.cancel_unstarted().unwrap();let mut other_action=None;assert!(other.drive(&mut actual,&mut other_action).unwrap());let mut other_reading=None;assert!(other_action.as_mut().unwrap().transfer_reading(&mut other_reading).unwrap());let other_observation=other_reading.take().unwrap().unwrap();assert!(other.should_yield(&actual,deadline,other_observation,1).is_err());other.finish(&actual,&mut other_action).unwrap();assert!(other.into_producer().is_ok());assert!(authority.into_producer().is_ok())
}

#[test]
fn recorded_clock_preserves_a_real_backward_reading_and_refuses_deadline_admission(){
 struct Scripted{issuer:OriginalSourceTurnIssuerIdentity,read:usize}
 impl OriginalClockProducer for Scripted{
  type Context<'a,'b>=OriginalSystemClockContext<'a> where 'b:'a;
  fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{if c.issuer.identity()!=self.issuer{return Err(invalid())}c.issuer.validate(c.turn)?;Ok(())}
  fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity> where 'b:'a{Some(c.turn.identity())}
  fn read<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,reply:OriginalClockReply<'r>)->Result<OriginalClockReplyComplete<'r>,ValueError> where 'b:'a{let reading=[1u128<<64,(1u128<<64)-1][self.read];self.read+=1;Ok(reply.complete(Ok(Some(reading))))}
  fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,reply:OriginalClockReply<'r>)->Result<OriginalClockReplyComplete<'r>,ValueError> where 'b:'a{Ok(reply.pending())}
 }
 let issuer=OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();let mut context=OriginalSystemClockContext::new(&issuer,&turn).unwrap();let mut owner=OriginalClockAuthority::new(Scripted{issuer:issuer.identity(),read:0});let mut action=None;let mut deadline=None;let mut first_observation=None;for (expected,monotonic) in [(1u128<<64,true),((1u128<<64)-1,false)]{assert!(owner.drive(&mut context,&mut action).unwrap());let mut output=None;assert!(action.as_mut().unwrap().transfer_reading(&mut output).unwrap());let observed=output.take().unwrap().unwrap();assert_eq!((observed.reading(),observed.monotonic()),(Some(expected),monotonic));if monotonic{deadline=Some(owner.deadline_from(&context,observed,100).unwrap());first_observation=Some(observed)}else{assert!(owner.should_yield(&context,deadline.unwrap(),first_observation.unwrap(),1).is_err());assert!(owner.should_yield(&context,deadline.unwrap(),observed,1).unwrap())}owner.finish(&context,&mut action).unwrap();if monotonic{let mut zero=OriginalClockDecisionFrame::new();assert_eq!(zero.poll(&mut owner,&mut context,deadline.unwrap(),0).unwrap(),OriginalClockDecisionStatus::Ready);let mut output=None;assert!(zero.transfer_decision(&mut output).unwrap());assert_eq!(output,Some(true));zero.finish(&mut owner,&context).unwrap();assert_eq!(owner.inspect(|producer|producer.read),1)}}assert_eq!(owner.into_producer().ok().unwrap().read,2)
}

#[test]
fn clock_retains_a_recorded_reading_and_an_independent_original_refusal(){
 struct Both{issuer:OriginalSourceTurnIssuerIdentity,error:Option<ValueError>,calls:usize}
 impl OriginalClockProducer for Both{
  type Context<'a,'b>=OriginalSystemClockContext<'a> where 'b:'a;
  fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{if c.issuer.identity()!=self.issuer{return Err(invalid())}c.issuer.validate(c.turn)?;Ok(())}
  fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity> where 'b:'a{Some(c.turn.identity())}
  fn read<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,reply:OriginalClockReply<'r>)->Result<OriginalClockReplyComplete<'r>,ValueError> where 'b:'a{self.calls+=1;let _reply=reply.complete(Ok(Some(42)));Err(self.error.take().unwrap())}
  fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,reply:OriginalClockReply<'r>)->Result<OriginalClockReplyComplete<'r>,ValueError> where 'b:'a{Ok(reply.pending())}
 }
 let issuer=OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();let mut context=OriginalSystemClockContext::new(&issuer,&turn).unwrap();let error=ValueError::new(ValueRefusalKind::Canceled,"actual clock source refusal".to_owned());let pointer=error.message.as_ptr();let mut owner=OriginalClockAuthority::new(Both{issuer:issuer.identity(),error:Some(error),calls:0});let(mut action,mut refusal,mut reading)=(None,None,None);assert!(!owner.drive(&mut context,&mut action).unwrap());assert!(action.as_mut().unwrap().transfer_refusal(&mut refusal).unwrap());assert_eq!(refusal.as_ref().unwrap().message.as_ptr(),pointer);assert!(owner.drive(&mut context,&mut action).unwrap());assert!(action.as_mut().unwrap().transfer_reading(&mut reading).unwrap());assert_eq!(reading.take().unwrap().unwrap().reading(),Some(42));owner.finish(&context,&mut action).unwrap();assert_eq!(owner.into_producer().ok().unwrap().calls,1)
}

#[test]
fn resident_deadline_decision_recovers_the_same_original_clock_reply(){
 let issuer=OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();let calls=Arc::new(AtomicUsize::new(0));let recoveries=Arc::new(AtomicUsize::new(0));let mut owner=OriginalClockAuthority::new(Interrupted{issuer:issuer.identity(),calls:calls.clone(),recoveries:recoveries.clone()});let mut context=OriginalSystemClockContext::new(&issuer,&turn).unwrap();let mut initial=None;assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||owner.drive(&mut context,&mut initial).unwrap())).is_err());assert!(owner.drive(&mut context,&mut initial).unwrap());let mut observation=None;assert!(initial.as_mut().unwrap().transfer_reading(&mut observation).unwrap());let deadline=owner.deadline_from(&context,observation.take().unwrap().unwrap(),1).unwrap();owner.finish(&context,&mut initial).unwrap();let mut frame=OriginalClockDecisionFrame::new();let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||frame.poll(&mut owner,&mut context,deadline,5).unwrap()));assert!(interrupted.is_err());assert!(!frame.terminal_is_empty());assert_eq!(frame.poll(&mut owner,&mut context,deadline,5).unwrap(),OriginalClockDecisionStatus::Ready);let mut output=None;assert!(frame.transfer_decision(&mut output).unwrap());assert_eq!(output,Some(false));frame.finish(&mut owner,&context).unwrap();assert!(frame.terminal_is_empty());assert_eq!(calls.load(Ordering::Relaxed),2);assert_eq!(recoveries.load(Ordering::Relaxed),0);assert!(owner.into_producer().is_ok())
}

#[test]
fn owned_host_clock_recovers_the_actual_recorded_reply(){
 struct Host{calls:usize,recoveries:usize}
 impl OriginalHostClockProducer for Host{
  fn read<'reply>(&mut self,_:&OriginalSystemClockContext<'_>,reply:OriginalClockReply<'reply>)->Result<OriginalClockReplyComplete<'reply>,ValueError>{self.calls+=1;let _reply=reply.complete(Ok(Some(77)));panic!("host after recorded reading")}
  fn recover<'reply>(&mut self,_:&OriginalSystemClockContext<'_>,reply:OriginalClockReply<'reply>)->Result<OriginalClockReplyComplete<'reply>,ValueError>{self.recoveries+=1;Ok(reply.pending())}
 }
 let issuer=OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();let foreign=OriginalSourceTurnIssuer::new();let other=foreign.issue().unwrap();let mut context=OriginalSystemClockContext::new(&issuer,&turn).unwrap();let mut wrong=OriginalSystemClockContext::new(&foreign,&other).unwrap();let mut clock=OriginalClockAuthority::new(OriginalHostClock::new(&issuer,Host{calls:0,recoveries:0}));let mut action=None;assert!(clock.drive(&mut wrong,&mut action).is_err());assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||clock.drive(&mut context,&mut action).unwrap())).is_err());assert!(clock.drive(&mut context,&mut action).unwrap());let mut reading=None;assert!(action.as_mut().unwrap().transfer_reading(&mut reading).unwrap());assert_eq!(reading.unwrap().unwrap().reading(),Some(77));clock.finish(&context,&mut action).unwrap();let host=clock.into_producer().ok().unwrap().into_host();assert_eq!((host.calls,host.recoveries),(1,0));
}

#[test]
fn erased_host_admission_denial_keeps_the_actual_source_owner(){
 use semio_framework_value_control_contract::{OriginalWork,OriginalWorkAuthority,OriginalWorkRecipient,OriginalWorkQuote,OriginalWorkQuoteComplete,OriginalWorkPartialCheck,OriginalWorkPartialCheckComplete,RetainedAllocationEffect,RetainedCloneGrant};
 struct Host(u8);impl OriginalHostClockProducer for Host{fn read<'r>(&mut self,_:&OriginalSystemClockContext<'_>,r:OriginalClockReply<'r>)->Result<OriginalClockReplyComplete<'r>,ValueError>{Ok(r.complete(Ok(Some(u128::from(self.0)))))}fn recover<'r>(&mut self,_:&OriginalSystemClockContext<'_>,r:OriginalClockReply<'r>)->Result<OriginalClockReplyComplete<'r>,ValueError>{Ok(r.pending())}}
 impl semio_framework_value_retirement::retirement::RetireOwned for Host{type RetirementCursor=semio_framework_value_retirement::retirement::Leaf<u8>;fn retirement_seed(self)->Self::RetirementCursor{semio_framework_value_retirement::retirement::leaf(self.0)}fn retirement_birth_bytes(&self)->Option<usize>{Some(semio_framework_value_retirement::retirement::leaf_birth_bytes::<u8>())}fn controlled_retirement_supported()->bool{true}}
 struct Work;impl OriginalWorkRecipient for Work{type Context<'a,'b>=() where 'b:'a;fn validate_context<'a,'b>(&self,_:&())->Result<(),ValueError> where 'b:'a{Ok(())}fn source_turn<'a,'b>(&self,_:&())->Option<OriginalSourceTurnIdentity> where 'b:'a{None}fn admits<'r,'a,'b>(&mut self,_:&mut (),q:OriginalWorkQuote<'r>,_:u64,_:u64)->OriginalWorkQuoteComplete<'r> where 'b:'a{q.complete(Ok(true))}fn settle_partial<'r,'a,'b>(&mut self,_:&mut (),c:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r> where 'b:'a{c.complete(Ok(()))}fn recover_partial<'r,'a,'b>(&mut self,_:&mut (),c:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r> where 'b:'a{c.pending()}}
 let cases:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/⏱️recorded/host-admission.json")).unwrap();assert_eq!(cases[0]["items"],0);assert_eq!(cases[0]["admitted"],false);let issuer=OriginalSourceTurnIssuer::new();let mut host=Some(OriginalClockAuthority::new(OriginalHostClock::new(&issuer,Host(77))));let mut payer=OriginalWorkAuthority::new(Work);payer.with_loan(&mut (),|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);let(mut action,mut receipt,mut actual)=(None,None,None);let mut output=None;assert_eq!(work.prepare_for_action(1000,&mut action).unwrap(),Some(true));work.issue_performed_for_action(action,&mut receipt).unwrap();{let mut effect=RetainedAllocationEffect::new(RetainedCloneGrant::default(),1,&mut actual,receipt.as_mut().unwrap());let turn=admit_original_host_clock(&mut host,&mut output,&mut effect);assert!(turn.result.unwrap().is_none());assert_eq!(turn.work,0)}assert!(actual.is_none()&&output.is_none());let grant=RetainedCloneGrant{maximum_items:100,maximum_copy_bytes:100000,maximum_capacity_bytes:100000,maximum_release_bytes:100000,maximum_depth:100};{let mut effect=RetainedAllocationEffect::new(grant,semio_framework_value_control_contract::OriginalWorkSink::remaining_work_units(receipt.as_ref().unwrap()).unwrap(),&mut actual,receipt.as_mut().unwrap());let turn=admit_original_host_clock(&mut host,&mut output,&mut effect);assert!(turn.result.unwrap().is_some())}assert!(host.is_none()&&actual.is_some());let dispatch=issuer.issue().unwrap();let mut context=OriginalSystemClockContext::new(&issuer,&dispatch).unwrap();let mut read_action=None;{let frame=output.as_mut().unwrap();assert!(frame.drive(&mut context,&mut read_action).unwrap());let mut reading=None;assert!(read_action.as_mut().unwrap().transfer_reading(&mut reading).unwrap());assert_eq!(reading.unwrap().unwrap().reading(),Some(77));frame.finish(&context,&mut read_action).unwrap()}for _ in 0..100{if output.as_ref().unwrap().terminal_is_empty(){break}let mut marker=None;let mut effect=RetainedAllocationEffect::new(grant,semio_framework_value_control_contract::OriginalWorkSink::remaining_work_units(receipt.as_ref().unwrap()).unwrap(),&mut marker,receipt.as_mut().unwrap());match output.as_mut().unwrap().step(&mut effect){semio_framework_value_control_contract::RetainedWorkPoll::Pending{..}=>{},semio_framework_value_control_contract::RetainedWorkPoll::Complete(turn)=>{assert!(turn.result.is_ok(),"{:?}",turn.result.as_ref().err())}}}assert!(output.as_ref().unwrap().terminal_is_empty());let released=output.as_ref().unwrap().frame_release_bytes();assert!(released>0&&released<=grant.maximum_release_bytes);{let mut marker=None;let mut effect=RetainedAllocationEffect::new(grant,semio_framework_value_control_contract::OriginalWorkSink::remaining_work_units(receipt.as_ref().unwrap()).unwrap(),&mut marker,receipt.as_mut().unwrap());assert!(effect.performed(1).unwrap());drop(output.take())}work.claim_performed_for_action(action,&mut receipt).unwrap();let mut partial=None;assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());let total=partial.take().unwrap().total();let mut proof=None;assert!(work.commit_for_action(total,action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut action).unwrap()}).unwrap();assert!(host.is_none());
}
